```c
#include <stdio.h>

int main(void) {
    int A, B;
    if (scanf("%d%d", &A, &B) != 2) {
        return 0;
    }

    int ana = A % 3;
    int bia = B % 3;

    if (bia == ana) {
        bia = (bia + 1) % 3;
    }

    for (int cadeira = 0; cadeira < 3; cadeira++) {
        if (cadeira != ana && cadeira != bia) {
            printf("%d\n", cadeira);
            break;
        }
    }

    return 0;
}
```

